import {mkdir, readFile, writeFile} from 'node:fs/promises';
import {resolve, join} from 'node:path';
const {chromium, expect: rawExpect}=createRequire(new URL('../../package.json',import.meta.url))('@playwright/test');
const args=Object.fromEntries(process.argv.slice(2).map(arg=>{const [key,...rest]=arg.replace(/^--/,'').split('=');return[key,rest.join('=')];}));
for(const key of Object.keys(args))if(!['base','out','view','manifest'].includes(key))throw new Error(`Unknown --${key}`);
const base=new URL(args.base||'http://127.0.0.1:4180/memory/'), view=args.view||'desktop';
if(base.search||base.hash||!['desktop','phone'].includes(view))throw new Error('Use a query-free base and desktop|phone view');
const output=resolve(args.out||`.work/publish-20261123/${view}-smoke`), original=view==='desktop'?{width:1280,height:800}:{width:390,height:844};
const alternate=view==='desktop'?{width:390,height:844}:{width:1280,height:800};
const manifest=args.manifest?JSON.parse(await readFile(args.manifest,'utf8')):null;
const expect=rawExpect.configure({timeout:180000}), sha=bytes=>createHash('sha256').update(bytes).digest('hex');
await mkdir(output,{recursive:true});
const report={schema:1,base:base.href,view,startedAt:new Date().toISOString(),method:{
  viewport:original,alternateViewport:alternate,dpr:1,motion:'no-preference',initialPointer:view==='phone'?'native touchscreen taps':'mouse',clock:'Native Date/performance/RAF, no freezing or timewarp',
  environment:'Production defaults and adaptive quality, no debugEnv or seeded preferences',
  isolation:'Fresh browser/context; no personal draft/editor page visited, no reload',
  media:'Native Audio constructor forwarding only; natural track end allowed only with ended/paused/time and matching UI',
  gl:'Native getError checked only after completed functional steps; no GL/render/renderer settings replaced',
  scope:'Visitor smoke, short landscape/small-screen menus, resized album textures; context loss fallback and enabled retry button, without actual reload retry',
  limits:'Software Chromium and dimensions are not real phone/Safari/listening/FPS or input-to-display measurements'},
  steps:[],screenshots:[],pageErrors:[],consoleErrors:[],warnings:[],failedRequests:[],httpErrors:[],glChecks:[]};
const save=()=>writeFile(join(output,'report.json'),JSON.stringify(report,null,2)+'\n');
let browser, context, page, phase='startup';
try{
  browser=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox','--enable-unsafe-swiftshader']});report.browser=browser.version();
  context=await browser.newContext({viewport:original,deviceScaleFactor:1,reducedMotion:'no-preference',hasTouch:view==='phone',timezoneId:'Asia/Shanghai'});
  page=await context.newPage();page.setDefaultTimeout(180000);page.setDefaultNavigationTimeout(180000);
  page.on('pageerror',error=>report.pageErrors.push({phase,message:error.message}));
