  page.on('requestfailed',request=>report.failedRequests.push({phase,url:request.url(),error:request.failure()?.errorText}));
  page.on('response',response=>{if(response.status()>=400)report.httpErrors.push({phase,url:response.url(),status:response.status()});});
  await page.addInitScript(()=>{const NativeAudio=window.Audio;function ObservedAudio(...sources){const element=new NativeAudio(...sources);window.__releaseAudio=element;return element;}
    ObservedAudio.prototype=NativeAudio.prototype;Object.setPrototypeOf(ObservedAudio,NativeAudio);window.Audio=ObservedAudio;});
  const state=()=>page.evaluate(()=>{const a=window.__releaseAudio;return{stage:document.body.dataset.stage,viewport:[innerWidth,innerHeight],dpr:devicePixelRatio,
    motion:matchMedia('(prefers-reduced-motion: reduce)').matches,quality:document.querySelector('#quality')?.textContent,
    title:document.querySelector('#chapter-title')?.textContent,chapter:document.querySelector('#chapter-count')?.textContent,
    record:document.querySelector('#record-state')?.textContent,timeOrigin:performance.timeOrigin,canvasCount:document.querySelectorAll('#world canvas').length,
    media:a?{source:a.currentSrc||a.src,paused:a.paused,ended:a.ended,muted:a.muted,time:a.currentTime,duration:Number.isFinite(a.duration)?a.duration:null,
