    if(gl)for(let n=0;n<8;n++){const code=gl.getError();if(!code)break;errors.push(code);if(code===0x9242)break;}return errors;});
    report.glChecks.push({name,errors,allowLoss});expect(errors.filter(code=>!(allowLoss&&code===0x9242)),name).toEqual([]);};
  const picture=async name=>{const path=join(output,`${name}.png`);await page.screenshot({path,timeout:180000});const b=await readFile(path);report.screenshots.push({name,path,bytes:b.length,sha256:sha(b)});};
