    else{expect(a.paused).toBe(false);expect(s.record).toBe('播放中');}return s;};
  const step=async(name,action,allowLoss=false)=>{phase=name;const started=performance.now();console.log(JSON.stringify({view,step:name,stage:'start'}));await action();await glCheck(name,allowLoss);
    report.steps.push({name,wallMs:performance.now()-started,at:new Date().toISOString(),state:await state()});await save();console.log(JSON.stringify({view,step:name,stage:'done'}));};
  const activate=locator=>view==='phone'?locator.tap():locator.click();
