    if(manifest){const body=await response.body();expect(sha(body)).toBe(manifest.files['index.html'].sha256);report.indexSHA256=sha(body);}
    await expect(page.locator('#loading')).toBeHidden();report.scripts=await page.locator('script[src]').evaluateAll(elements=>elements.map(e=>e.src));
    expect(report.scripts.some(src=>/\/assets\/[^/?]+\.js/.test(src))).toBe(true);expect(report.scripts.some(src=>/\/src\//.test(src))).toBe(false);
    expect((await state()).motion).toBe(false);});
  const origin=(await state()).timeOrigin;
  await step('fog-door-entry',async()=>{await activate(page.locator('#enter'));await expect(page.locator('#enter-label')).toHaveText('推开这扇门');await expect(page.locator('#enter')).toBeEnabled();
    await activate(page.locator('#enter'));await expect(page.locator('#room-ui')).toBeVisible();await expect(page.locator('body')).toHaveAttribute('data-stage','room');});
  await step('native-default-music',async()=>{await expect(page.locator('#record-state')).toHaveText('播放中');await page.waitForFunction(()=>window.__releaseAudio?.currentTime>.05);
    const s=await healthyMusic();expect(s.media.source).toMatch(/default-record.*\.mp3/);expect(s.media.duration).toBeGreaterThan(60);await picture('room');});
  await step('record-panel-pause-play-mute',async()=>{await page.locator('#room-settings').click();await expect(page.locator('#room-settings-menu')).toBeVisible();
    const chooser=page.waitForEvent('filechooser');await page.locator('#choose-record').click();await(await chooser).setFiles([]);await expect(page.locator('#record-panel')).toBeVisible();
    await page.locator('#record-panel-toggle').click();await expect(page.locator('#record-state')).toHaveText('已暂停');expect((await state()).media.paused).toBe(true);
    await page.locator('#record-panel-toggle').click();await expect(page.locator('#record-state')).toHaveText('播放中');const time=(await state()).media.time;
    await page.waitForFunction(t=>window.__releaseAudio.currentTime>t+.05,time);await page.keyboard.press('Escape');await expect(page.locator('#record-panel')).toBeHidden();await page.keyboard.press('Escape');
    await expect(page.locator('#room-settings-menu')).toBeHidden();await page.locator('#sound').click();await expect(page.locator('#sound')).toHaveAttribute('aria-pressed','false');expect((await state()).media.muted).toBe(true);
