  await step('small-phone-settings',async()=>{await page.setViewportSize({width:320,height:568});report.smallPanels=[];
    for(const [button,panel] of [['room-light','room-light-panel'],['time-flow','time-flow-panel']]){await page.locator('#room-settings').click();await expect(page.locator('#room-settings-menu')).toBeVisible();
