    await expect(page.locator('#open-book')).toBeHidden();await expect(page.locator('#pet-cat')).toBeEnabled();await page.setViewportSize({width:844,height:390});await page.locator('#room-settings').click();
    await expect(page.locator('#room-settings-menu')).toBeVisible();report.catMenu=await page.evaluate(()=>({viewport:[innerWidth,innerHeight],menu:document.querySelector('#room-settings-menu').getBoundingClientRect().toJSON(),
      room:document.querySelector('#room-ui').getBoundingClientRect().toJSON(),centre:document.elementFromPoint(innerWidth/2,innerHeight/2)?.tagName}));
    expect(report.catMenu.menu.left).toBeGreaterThanOrEqual(report.catMenu.room.left);expect(report.catMenu.menu.right).toBeLessThanOrEqual(report.catMenu.room.right);expect(report.catMenu.centre).toBe('CANVAS');
    await picture('cat-menu');await page.keyboard.press('Escape');await page.setViewportSize(original);
    await page.evaluate(()=>{const button=document.querySelector('#pet-cat');window.__releasePet=[];window.__releasePetObserver=new MutationObserver(()=>window.__releasePet.push({busy:button.dataset.busy??null,disabled:button.disabled}));
