const [base, out, sourceCommit] = process.argv.slice(2);
await mkdir(out,{recursive:true});
const report={base,sourceCommit,startedAtUTC:new Date().toISOString(),method:'Fresh isolated browser context with generated default test draft only; no existing author context or personal draft is opened. Native editor/preview assets and IndexedDB, no mocks.',errors:[],consoleErrors:[],failedRequests:[],httpErrors:[]};
const browser=await chromium.launch({executablePath:'/usr/bin/chromium',args:['--no-sandbox','--enable-unsafe-swiftshader']});
try {
 const context=await browser.newContext({viewport:{width:1280,height:900},timezoneId:'Asia/Shanghai'});
 const page=await context.newPage();page.setDefaultTimeout(90000);
 page.on('pageerror',e=>report.errors.push(e.message));page.on('console',m=>{if(m.type()==='error')report.consoleErrors.push(m.text());});
 page.on('requestfailed',r=>report.failedRequests.push({url:r.url(),error:r.failure()?.errorText}));
 page.on('response',r=>{if(r.status()>=400)report.httpErrors.push({url:r.url(),status:r.status()});});
 await page.goto(new URL('editor.html',base).href,{waitUntil:'domcontentloaded'});
 await expect(page.locator('#document-title')).toBeVisible();await expect(page.locator('#save-status')).toHaveAttribute('data-state','saved',{timeout:90000});
 report.testDraftBaseCommit=await page.evaluate(()=>new Promise((resolve,reject)=>{
  const open=indexedDB.open('tides-album-v1',1);open.onerror=()=>reject(open.error);open.onsuccess=()=>{
   const db=open.result,tx=db.transaction('drafts','readonly'),get=tx.objectStore('drafts').get('current');
   get.onsuccess=()=>resolve(get.result?.document?.baseCommit);get.onerror=()=>reject(get.error);tx.oncomplete=()=>db.close();
  };
 }));
 assert.equal(report.testDraftBaseCommit,sourceCommit);
 await page.screenshot({path:out+'/editor.png'});
 await page.locator('#preview').click();const frame=page.frameLocator('#preview-frame');
 await expect(frame.locator('#reader')).toHaveAttribute('data-phase','ready',{timeout:90000});
 report.previewChapter=await frame.locator('#chapter-count').textContent();
 await expect(frame.locator('#book .page-left')).toBeVisible();await expect(frame.locator('#book .page-right')).toBeVisible();
 await page.locator('#preview-mobile').click();await expect(page.locator('#preview-frame')).toHaveCSS('width','390px');
 report.editorCanvasCount=await page.locator('#world canvas').count();
 report.previewCanvasCount=await frame.locator('#world canvas').count();
 assert.equal(report.editorCanvasCount,0);assert.equal(report.previewCanvasCount,0);
 await page.screenshot({path:out+'/preview.png'});await page.locator('#close-preview').click();
 await expect(page.locator('#preview-dialog')).not.toBeVisible();
 assert.deepEqual(report.errors,[]);assert.deepEqual(report.consoleErrors,[]);assert.deepEqual(report.failedRequests,[]);assert.deepEqual(report.httpErrors,[]);
 report.passed=true;await context.close();
}catch(e){report.passed=false;report.failure=String(e.stack??e);process.exitCode=1;}
finally{await browser.close();report.finishedAtUTC=new Date().toISOString();await writeFile(out+'/report.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({passed:report.passed,sourceCommit:report.testDraftBaseCommit,failure:report.failure}));}

