import argparse, concurrent.futures, datetime, hashlib, json, pathlib, re, time, urllib.parse, urllib.request

args=argparse.ArgumentParser()
args.add_argument('--base',required=True);args.add_argument('--version',required=True)
args.add_argument('--out',required=True);args.add_argument('--manifest',default='.work/publish-20261123/manifest.json')
args.add_argument('--retry-report')
opt=args.parse_args();manifest=json.loads(pathlib.Path(opt.manifest).read_text())
files=manifest['files'];out=pathlib.Path(opt.out);out.parent.mkdir(parents=True,exist_ok=True)
selected=list(files)
if opt.retry_report:
 previous=json.loads(pathlib.Path(opt.retry_report).read_text());selected=[r['path'] for r in previous['results'] if not r['passed']]
def request(url,start=None,end=None):
 headers={'User-Agent':'memory-release-verification','Cache-Control':'no-cache','Accept-Encoding':'identity'}
 if start is not None:headers['Range']=f'bytes={start}-{end}'
 with urllib.request.urlopen(urllib.request.Request(url,headers=headers),timeout=40) as r:
  return r.status,dict(r.headers),r.read()
def verify(name):
 target=files[name];url=urllib.parse.urljoin(opt.base,'' if name=='index.html' else urllib.parse.quote(name,safe='/'))
 url+='?v='+urllib.parse.quote(opt.version);attempts=[];started=time.monotonic()
 for attempt in range(1,4):
  try:
   if attempt==1 or target['bytes']<=524288:
    status,headers,data=request(url);assert status==200,(status,name)
   else:
    chunks=[]
    for start in range(0,target['bytes'],262144):
     end=min(start+262143,target['bytes']-1);status,headers,data=request(url,start,end)
     if status==200:
      assert len(data)==target['bytes'] and hashlib.sha256(data).hexdigest()==target['sha256']
      chunks=[data];break
     assert status==206,(status,start,end)
     value=next((v for k,v in headers.items() if k.lower()=='content-range'),'')
     assert value==f'bytes {start}-{end}/{target["bytes"]}',value
     assert len(data)==end-start+1,(len(data),start,end);chunks.append(data)
    data=b''.join(chunks)
   digest=hashlib.sha256(data).hexdigest()
   assert len(data)==target['bytes'],(len(data),target['bytes'])
   assert digest==target['sha256'],(digest,target['sha256'])
   attempts.append({'attempt':attempt,'passed':True,'bytes':len(data)})
   return {'path':name,'passed':True,'bytes':len(data),'sha256':digest,'seconds':time.monotonic()-started,'attempts':attempts}
  except Exception as e:attempts.append({'attempt':attempt,'passed':False,'error':str(e)})
 return {'path':name,'passed':False,'seconds':time.monotonic()-started,'attempts':attempts}
report={'sourceCommit':manifest['sourceCommit'],'base':opt.base,'version':opt.version,'startedAtUTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),
 'method':'Complete file bytes and SHA-256,6HTTPworkers. Failed full downloads retry; >512KiB retries use strict256KiB Range/206/Content-Range or verified complete200. No sampled-only file checks.',
 'expectedFiles':len(files),'selectedFiles':len(selected),'results':[]}
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
 for r in pool.map(verify,selected):
  report['results'].append(r)
  if not r['passed']:print(json.dumps(r),flush=True)
